/* My Kost - js/effects.js : Animasi masuk halaman dan hitung naik angka statistik */
function countUp(el){if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const m=el.textContent.match(/^(Rp)?([\d.]+)(%?)$/);if(!m)return;const end=parseInt(m[2].replace(/\./g,''),10),t0=performance.now(),fin=el.textContent;if(!(end>0))return;const f=t=>{const k=Math.min((t-t0)/800,1),e=1-Math.pow(1-k,3);el.textContent=k<1?(m[1]||'')+Math.round(end*e).toLocaleString('id-ID')+m[3]:fin;if(k<1)requestAnimationFrame(f)};requestAnimationFrame(f)}
function enter(){const a=$('#app');a.classList.remove('in');void a.offsetWidth;a.classList.add('in');a.querySelectorAll('.top,.ban,.fl,.c').forEach((e,i)=>e.style.setProperty('--i',Math.min(i,14)));a.querySelectorAll('.st b').forEach(countUp);clearTimeout(enter.t);enter.t=setTimeout(()=>a.classList.remove('in'),1400)}
